// ---------------------------------------------------------
// Server (guild) rail
// ---------------------------------------------------------
function guildInitials(name) {
    const words = name.replace(/[^\w\s]/g, '').trim().split(/\s+/).filter(Boolean);
    return (words.slice(0, 2).map((w) => w[0]).join('') || '?').toUpperCase();
}

function renderServerBar() {
    const container = $('server-bar-guilds');
    container.innerHTML = '';
    for (const guild of state.guilds) {
        const el = document.createElement('div');
        el.className = 'server-icon';
        el.dataset.guildId = guild.guild_id;
        el.title = `${guild.name} — ${fmtNum(guild.message_count)} msgs`;
        el.innerHTML = `<div class="guild-initials">${escapeHtml(guildInitials(guild.name))}</div>`;
        el.addEventListener('click', () => selectGuild(guild.guild_id));
        container.appendChild(el);
    }
}

function selectGuild(guildId) {
    const guild = state.guilds.find((g) => g.guild_id === guildId);
    if (!guild) return;
    state.currentGuildId = guildId;
    state.categories = guild.categories;
    document.querySelectorAll('#server-bar-guilds .server-icon').forEach((el) =>
        el.classList.toggle('active', el.dataset.guildId === guildId));
    $('server-name').textContent = guild.name;
    renderChannels();
}

